from collections import deque
def regions(g):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]==0 and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); comp=[]; enc=True
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if not(0<=a<R and 0<=b<C): enc=False; continue
                        if g[a][b]==0 and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
                out.append((comp,enc))
    return out
