# try to find Hamiltonian path over 5-cells (8-conn) in demo between the two degree-1 cells
import sys
from functools import lru_cache
def ham_path(S, start, end):
    S=list(S); n=len(S); idx={c:i for i,c in enumerate(S)}
    nbr={c:[d for d in S if d!=c and abs(d[0]-c[0])<=1 and abs(d[1]-c[1])<=1] for c in S}
    sys.setrecursionlimit(10000)
    seen=set()
    def dfs(c, path):
        if len(path)==n: return path if path[-1]==end else None
        for d in sorted(nbr[c], key=lambda d: len(nbr[d])):
            if d not in seen:
                seen.add(d); path.append(d)
                r=dfs(d,path)
                if r: return r
                path.pop(); seen.discard(d)
        return None
    seen.add(start)
    return dfs(start,[start])
