def zero_regions(g):
    R,C=len(g),len(g[0]); seen=set(); regs=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]==0 and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); comp=[]
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<R and 0<=b<C and g[a][b]==0 and (a,b) not in seen:
                            seen.add((a,b)); q.append((a,b))
                regs.append(comp)
    return regs
def border7(g):
    R,C=len(g),len(g[0]); res=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]!=0: continue
            if not(i in(0,R-1) or j in(0,C-1)): continue
            n=[]
            if i==0: n.append(g[0][j-1] if j>0 else None)
            if i==R-1: n.append(g[R-1][j-1] if j>0 else None)
            if j==0: n.append(g[i-1][0] if i>0 else None)
            if j==C-1: n.append(g[i-1][C-1] if i>0 else None)
            # neighbors along the border on each side
            nb=set()
            if j>0 and (i==0 or i==R-1): nb.add(g[i][j-1])
            if j<C-1 and (i==0 or i==R-1): nb.add(g[i][j+1])
            if i>0 and (j==0 or j==C-1): nb.add(g[i-1][j])
            if i<R-1 and (j==0 or j==C-1): nb.add(g[i+1][j])
            if len(nb)>=2 and nb=={5}: res.append((i,j))
    return res
